INSERT INTO ilb_psoriasis_cross_modality_intersection
(intersection_id,modality_code,control_zone,target_node,direction_code,intersection_class,evidence_status,human_psoriasis_evidence,mechanism_statement,claim_boundary,required_measurement,redundancy_group,complementary_group)
VALUES
('P126-NBUVB-IMMUNE','NB_UVB','IMMUNE','cutaneous inflammatory drive / IL23-Th17-IL17 network','DOWN','DIRECT_CONVERGENCE','ESTABLISHED','DIRECT','Phototherapy has established psoriasis efficacy and suppresses cutaneous inflammatory activity while affecting epidermal hyperplasia.','Do not reduce its action to one cytokine or assume durability.','delivered UVB dose; PASI/BSA; target lesion geometry','DIRECT_SKIN_CONTROL','CORE_IK'),
('P126-NBUVB-EPI','NB_UVB','EPIDERMAL','keratinocyte hyperproliferation / epidermal thickness','NORMALIZE','DIRECT_CONVERGENCE','ESTABLISHED','DIRECT','NB-UVB directly addresses abnormal epidermal growth in psoriasis.','Requires controlled phototherapy exposure and safety governance.','target thickness; V_excess; standardized photo','DIRECT_SKIN_CONTROL','CORE_IK'),
('P126-INDIR-IMMUNE','INDIRUBIN','IMMUNE','IL17A-TAK1-CCL20 keratinocyte feedback','DOWN','DIRECT_CONVERGENCE','SUPPORTED','DIRECT','Indirubin/indigo naturalis has human psoriasis efficacy and mechanistic evidence attenuating inflammatory keratinocyte feedback.','Formulation-specific evidence; do not generalize to all indigo products or traditional medicine.','defined formulation/exposure; PASI; CCL20/IL17-linked markers where available','DIRECT_MOLECULE_IK','CORE_IK'),
('P126-INDIR-EPI','INDIRUBIN','EPIDERMAL','EGFR/CDC25B; PCNA; cell-cycle/differentiation','NORMALIZE','DIRECT_CONVERGENCE','SUPPORTED','DIRECT','Indirubin inhibits epidermal growth signaling and is associated with reduced proliferation and improved differentiation markers.','Do not infer barrier normalization or durable cure from PASI response alone.','PCNA/Ki67; involucrin; lesion thickness; V_excess','DIRECT_MOLECULE_IK','CORE_IK'),
('P126-CURC-IMMUNE','CURCUMIN','IMMUNE','IL17/IL23/TNF inflammatory axis','DOWN','DIRECT_CONVERGENCE','PRELIMINARY','DIRECT_SMALL_TRIAL','Small topical psoriasis pilot reported reduced IL17/IL23/IL22/TNF expression.','Very small human study; formulation-dependent; not treatment-standard evidence.','defined formulation; PASI; cytokine markers','DIRECT_MOLECULE_IK','CORE_IK'),
('P126-CURC-EPI','CURCUMIN','EPIDERMAL','Ki67/proliferation and differentiation markers','NORMALIZE','DIRECT_CONVERGENCE','PRELIMINARY','DIRECT_SMALL_TRIAL','Small topical pilot reported reduced Ki67 alongside clinical lesion improvement.','Pilot evidence only.','Ki67; target lesion geometry','DIRECT_MOLECULE_IK','CORE_IK'),
('P126-BARRIER-BARRIER','BARRIER_CARE','BARRIER','stratum-corneum resistance / TEWL / fissure-scale state','NORMALIZE','DIRECT_CONVERGENCE','SUPPORTED','DIRECT_SUPPORT','Barrier-directed care acts directly on downstream physical barrier state.','Barrier improvement is not proof of immune normalization.','TEWL; hydration; fissure/scale; photos','BARRIER_SUPPORT','CORE_B'),
('P126-VITD-EPI','VITAMIN_D','EPIDERMAL','VDR-linked keratinocyte differentiation','NORMALIZE','BIOLOGICAL_CONVERGENCE','MIXED_SUPPORTED','MIXED','Vitamin-D/VDR biology intersects keratinocyte differentiation and immune regulation; psoriasis supplementation outcomes are inconsistent.','Use only when measured deficiency/clinical indication exists; no universal psoriasis dosing claim.','25OH-D; PASI; differentiation markers where research-grade','NUTRIENT_MODIFIER','COND_VITD'),
('P126-VITD-IMMUNE','VITAMIN_D','IMMUNE','cytokine regulation','NORMALIZE','BIOLOGICAL_CONVERGENCE','MIXED_SUPPORTED','MIXED','Vitamin D has immunomodulatory biology and some psoriasis adjunct evidence, especially with phototherapy.','Do not infer cytokine correction from serum 25OH-D alone.','25OH-D; relevant cytokines; PASI','NUTRIENT_MODIFIER','COND_VITD'),
('P126-PROBIO-IMMUNE','PROBIOTIC','IMMUNE','gut-systemic inflammatory modifiers / CRP','DOWN','SYSTEM_CONVERGENCE','PRELIMINARY_SUPPORTED','DIRECT_META_SIGNAL','Probiotic RCT meta-analyses report PASI and CRP improvement, indicating a gut-systemic inflammatory intersection.','No universal strain, dose, or gut-to-IL17 coefficient.','defined strain/dose; PASI; CRP; GI state','GUT_MODIFIER','COND_MICRO'),
('P126-METAB-IMMUNE','METABOLIC_CORRECTION','IMMUNE','metabolic inflammatory amplification','DOWN','SYSTEM_CONVERGENCE','SUPPORTED_CONDITIONAL','DIRECT_SELECTED','Weight/metabolic correction can reduce psoriasis activity in selected overweight/obese populations.','Conditional on measured metabolic state; not universal.','weight/waist; metabolic labs; PASI','METABOLIC_MODIFIER','COND_METAB'),
('P126-MINDFUL-ANS','MINDFULNESS_CBT','NEURO_AUTONOMIC','threat/stress/autonomic state','NORMALIZE','UPSTREAM_CONVERGENCE','SUPPORTED','DIRECT','Multiple psoriasis RCTs show short-term improvement in skin severity and quality of life with mindfulness/meditation.','Clinical improvement does not prove IL17 mediation.','stress scale; HRV if used; PASI/BSA','STRESS_REGULATION','COND_ANS'),
