-- Phase 126: Psoriasis cross-modality intersection matrix
-- Purpose: expose convergence across modalities without promoting weak evidence to mechanism.

CREATE TABLE IF NOT EXISTS ilb_psoriasis_cross_modality_intersection (
  intersection_id VARCHAR(96) PRIMARY KEY,
  modality_code VARCHAR(96) NOT NULL,
  control_zone VARCHAR(64) NOT NULL,
  target_node VARCHAR(128) NOT NULL,
  direction_code VARCHAR(32) NOT NULL,
  intersection_class VARCHAR(32) NOT NULL,
  evidence_status VARCHAR(32) NOT NULL,
  human_psoriasis_evidence VARCHAR(32) NOT NULL,
  mechanism_statement TEXT NOT NULL,
  claim_boundary TEXT NOT NULL,
  required_measurement TEXT NOT NULL,
  redundancy_group VARCHAR(64) NULL,
  complementary_group VARCHAR(64) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

ON DUPLICATE KEY UPDATE evidence_status=VALUES(evidence_status),human_psoriasis_evidence=VALUES(human_psoriasis_evidence),mechanism_statement=VALUES(mechanism_statement),claim_boundary=VALUES(claim_boundary),required_measurement=VALUES(required_measurement);

CREATE OR REPLACE VIEW v_ilb_psoriasis_intersection_zones AS
SELECT control_zone, COUNT(DISTINCT modality_code) AS modality_count,
       SUM(intersection_class IN ('DIRECT_CONVERGENCE','BIOLOGICAL_CONVERGENCE','SYSTEM_CONVERGENCE','UPSTREAM_CONVERGENCE')) AS biologically_grounded_links,
       SUM(intersection_class='NARRATIVE_CONVERGENCE') AS narrative_links
FROM ilb_psoriasis_cross_modality_intersection
GROUP BY control_zone;
